// documentation for more info.
func (u *WalkthroughUpsertBulk) Update(set func(*WalkthroughUpsert)) *WalkthroughUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(update *sql.UpdateSet) {
		set(&WalkthroughUpsert{UpdateSet: update})
	}))
	return u
}

